// レベル別取得関数
export function getBasicVocabulary(): VocabularyEntry[] {
  return BASIC_VOCABULARY
}

export function getIntermediateVocabulary(): VocabularyEntry[] {
  return INTERMEDIATE_VOCABULARY
}

export function getAdvancedVocabulary(): VocabularyEntry[] {
  return ADVANCED_VOCABULARY_3400
}

export function getExpertVocabulary(): VocabularyEntry[] {
  return EXPERT_VOCABULARY_3000
}

export function getCompleteVocabulary(): VocabularyEntry[] {
  return COMPLETE_VOCABULARY
}

export function getRandomBasicVocabulary(count: number): VocabularyEntry[] {
  const shuffled = [...BASIC_VOCABULARY].sort(() => Math.random() - 0.5)
  return shuffled.slice(0, count)
}

export function getRandomIntermediateVocabulary(count: number): VocabularyEntry[] {
  const shuffled = [...INTERMEDIATE_VOCABULARY].sort(() => Math.random() - 0.5)
  return shuffled.slice(0, count)
}

export function getRandomAdvancedVocabulary(count: number): VocabularyEntry[] {
  const shuffled = [...ADVANCED_VOCABULARY_3400].sort(() => Math.random() - 0.5)
  return shuffled.slice(0, count)
}

export function getRandomExpertVocabulary(count: number): VocabularyEntry[] {
  const shuffled = [...EXPERT_VOCABULARY_3000].sort(() => Math.random() - 0.5)
  return shuffled.slice(0, count)
}

export function getRandomCompleteVocabulary(count: number): VocabularyEntry[] {
  const shuffled = [...COMPLETE_VOCABULARY].sort(() => Math.random() - 0.5)
  return shuffled.slice(0, count)
}

export function searchCompleteVocabulary(query: string): VocabularyEntry[] {
  const lowerQuery = query.toLowerCase()
  return COMPLETE_VOCABULARY.filter(v => 
    v.word.toLowerCase().includes(lowerQuery) ||
    v.meanings.some(m => m.toLowerCase().includes(lowerQuery))
  )
}

export function getVocabularyByLevel(level: string): VocabularyEntry[] {
  if (level === 'basic') return BASIC_VOCABULARY
  if (level === 'intermediate') return INTERMEDIATE_VOCABULARY
  if (level === 'advanced') return ADVANCED_VOCABULARY_3400
  if (level === 'expert') return EXPERT_VOCABULARY_3000
  if (level === 'complete' || level === 'all') return COMPLETE_VOCABULARY
  return []
}

// 後方互換性のための関数
export function getAllVocabulary(): VocabularyEntry[] {
  return COMPLETE_VOCABULARY
}

export function getRandomVocabulary(count: number): VocabularyEntry[] {
  return getRandomCompleteVocabulary(count)
}

// 後方互換性のためのエクスポート
export const CLEAN_VOCABULARY = COMPLETE_VOCABULARY
export const ADVANCED_VOCABULARY = ADVANCED_VOCABULARY_3400  // 後方互換性
export const EXPERT_VOCABULARY = EXPERT_VOCABULARY_3000  // 専門レベル

export default COMPLETE_VOCABULARY

